package com.bare.walls; public final class WallpaperCaptureState { private final boolean home,lock,reused; private final long size; public WallpaperCaptureState(boolean home,boolean lock,boolean reused,long size){this.home=home;this.lock=lock;this.reused=reused;this.size=Math.max(0,size);} public boolean hasHome(){return home;} public boolean hasLock(){return lock;} public boolean isReused(){return reused;} public long getSize(){return size;} }